  "setup.auddSaved": {"fr": "Clé AudD ajoutée, c'est prêt.", "en": "AudD key added, you're ready.", "es": "Clave de AudD agregada, todo listo.", "zh": "AudD 密钥已添加，一切就绪。", "ar": "تمت إضافة مفتاح AudD، أنت جاهز."},
  "setup.clientIdSaved": {"fr": "Client ID enregistré. Plus qu'à te connecter !", "en": "Client ID saved. Now just sign in!", "es": "Client ID guardado. ¡Ahora solo inicia sesión!", "zh": "Client ID 已保存。登录一下就大功告成啦！", "ar": "تم حفظ Client ID. لم يبقَ سوى تسجيل الدخول!"},
  "setup.googleSaved": {"fr": "Fichier bien reçu. Tu peux supprimer le JSON téléchargé, puis « Se connecter avec Google ».", "en": "Got the file. You can delete the downloaded JSON, then \"Sign in with Google\".", "es": "Recibimos el archivo. Ya puedes borrar el JSON descargado y luego «Iniciar sesión con Google».", "zh": "文件已收到。你可以删掉下载的 JSON，然后点“使用 Google 登录”。", "ar": "وصل الملف! يمكنك حذف ملف JSON الذي نزّلته، ثم الضغط على «تسجيل الدخول عبر Google»."},
  "setup.removeConfirm": {"fr": "Retirer {what} de Carte ? Tu pourras le rebrancher quand tu veux.", "en": "Remove {what} from Carte? You can hook it up again any time.", "es": "¿Quitar {what} de Carte? Puedes volver a conectarlo cuando quieras.", "zh": "要把 {what} 从 Carte 移除吗？你随时可以重新连接。", "ar": "إزالة {what} من Carte؟ يمكنك إعادة ربطه في أي وقت."},
  "setup.removed": {"fr": "{what} retiré de Carte.", "en": "{what} removed from Carte.", "es": "Se quitó {what} de Carte.", "zh": "已从 Carte 中移除{what}。", "ar": "تمت إزالة {what} من Carte."},
