  "tv.noCode": {"fr": "Pas de code pays pour chercher des chaînes.", "en": "No country code to look up channels.", "es": "No hay código de país para buscar canales.", "zh": "没有可用于查询频道的国家代码。", "ar": "لا يوجد رمز دولة للبحث عن القنوات."},
  "tv.loading": {"fr": "Chargement des chaînes…", "en": "Loading channels…", "es": "Cargando canales…", "zh": "正在加载频道…", "ar": "جارٍ تحميل القنوات…"},
